    if (hostChainIsArbitrum) revert DataBlobsNotSupported();
    (bytes32 dataHash, IBridge.TimeBounds memory timeBounds, uint256 blobGas) = formBlobDataHash(afterDelayedMessagesRead);
    // ... rest of function
}

Add access control to removeDelayAfterFork, or prevent it from being called more than once, or only allow it to be called by authorized parties:

bool private _forkDelayRemoved;

function removeDelayAfterFork() external onlyRollupOwner {
    if (!_chainIdChanged()) revert NotForked();
    if (_forkDelayRemoved) revert AlreadyInit();
    _forkDelayRemoved = true;
    delayBlocks = 1;
    futureBlocks = 1;
    delaySeconds = 1;
    futureSeconds = 1;
}

Alternatively, restrict to onlyRollupOwner to prevent griefing.

Either revert when the buffer is not updatable but new delayed messages are being consumed (requiring a non-proof path), or always validate the proof regardless of updatability:

function delayProofImpl(uint256 afterDelayedMessagesRead, DelayProof memory delayProof) internal {
    if (afterDelayedMessagesRead > totalDelayedMessagesRead) {
        bytes32 delayedAcc = bridge.delayedInboxAccs(totalDelayedMessagesRead);
        if (!Messages.isValidDelayedAccPreimage(delayedAcc, delayProof.beforeDelayedAcc, delayProof.delayedMessage)) {
            revert InvalidDelayedAccPreimage();
        }
        if (buffer.isUpdatable()) {
            buffer.update(delayProof.delayedMessage.blockNumber);
        }
    }
}

Add a guard to check that the second child creation block is greater than the first child creation block before computing the difference:

uint256 secondChildBlock = assertionChain.getSecondChildCreationBlock(claimStateData.prevAssertionHash);
uint256 firstChildBlock = assertionChain.getFirstChildCreationBlock(claimStateData.prevAssertionHash);
if (secondChildBlock > firstChildBlock) {
    assertionBlocks = uint64(secondChildBlock - firstChildBlock);
} else {
    assertionBlocks = 0;
}

Also add a check that `secondChildBlock > 0` before using it.

Add access control so only the edge's staker can trigger the refund:

function refundStake(bytes32 edgeId) public {
    ChallengeEdge storage edge = store.get(edgeId);
    require(msg.sender == edge.staker, 'Only staker can refund');
    edge.setRefunded();
    IERC20 st = stakeToken;
    uint256 sa = stakeAmounts[edge.level];
    if (address(st) != address(0) && sa != 0) {
        st.safeTransfer(edge.staker, sa);
    }
    emit EdgeRefunded(edgeId, store.edges[edgeId].mutualId(), address(st), sa);
}

Alternatively, restrict to msg.sender == edge.staker OR an authorized refunder role.

Store the stake amount at the time of edge creation within the edge struct itself:

// In edge creation:
edge.stakeAmount = sa; // store deposited amount

// In refundStake:
uint256 sa = edge.stakeAmount; // use stored amount, not current stakeAmounts[level]

This ensures stakers always receive exactly what they deposited, regardless of parameter changes after deployment.

Apply a nonReentrant modifier to all state-changing functions:

import '@openzeppelin/contracts-upgradeable/security/ReentrancyGuardUpgradeable.sol';

contract EdgeChallengeManager is IEdgeChallengeManager, Initializable, ReentrancyGuardUpgradeable {
    function createLayerZeroEdge(...) external nonReentrant returns (bytes32) { ... }
    function refundStake(bytes32 edgeId) public nonReentrant { ... }
    function confirmEdgeByTime(...) public nonReentrant { ... }
}

Alternatively, move the token transfer before edge state creation (checks-effects-interactions pattern), though this is more complex given the need to know hasRival first.
